export function evaluate({ inputs, time }) {
  const g = 9.8;
  const v0 = Number(inputs.launchSpeed);
  const tTop = v0 / g;
  const hTop = (v0 * v0) / (2 * g);
  const duration = (2 * v0) / g;
  const currentT = Math.min(Math.max(0, time), duration);

  const velocity = v0 - g * currentT;
  const height = Math.max(0, v0 * currentT - 0.5 * g * currentT * currentT);

  let mState = "Moving up";
  if (Math.abs(velocity) < 0.05) {
    mState = "Still for an instant";
  } else if (velocity < 0) {
    mState = "Moving down";
  }
  const gState = "Gravity pulls down";

  const originX = 220;
  const originY = 360;
  const scaleY = 180;

  const ballX = originX;
  const ballY = originY - height * scaleY;

  const frameObjects = [];

  const lane = sdk.panel({
    id: "lane.main",
    x: 40,
    y: 30,
    w: 560,
    h: 370,
    title: "Vertical Toss",
    state: `${mState} | ${gState}`
  });
  frameObjects.push(...lane);

  const yAxis = sdk.axis("axis.y", {
    x: 100,
    y: originY,
    length: 300,
    orientation: "y",
    min: 0,
    max: 1.5,
    ticks: [0, 0.5, 1.0, 1.5],
    label: "Height",
    unit: "m"
  });
  frameObjects.push(yAxis);

  const launchGuide = sdk.line("heightGuide", 90, originY, 340, originY, {
    role: "neutral",
    opacity: 0.5
  });
  const launchText = sdk.text("launchLabel", 345, originY + 4, "Launch height (0 m)", {
    role: "neutral"
  });
  frameObjects.push(launchGuide, launchText);

  const ball = sdk.circle("ball.toss", ballX, ballY, 28, {
    role: "learner"
  });
  frameObjects.push(ball);

  const vVector = sdk.vector(
    "vec.v",
    { x: ballX - 35, y: ballY },
    {
      value: velocity,
      direction: "up",
      scale: 18,
      minLength: 10,
      label: "v",
      role: "input"
    }
  );
  frameObjects.push(...vVector);

  const aVector = sdk.vector(
    "vec.a",
    { x: ballX + 35, y: ballY },
    {
      value: -g,
      direction: "up",
      scale: 4,
      minLength: 10,
      label: "a (gravity)",
      role: "warning"
    }
  );
  frameObjects.push(...aVector);

  const calloutLines = [
    `v = ${sdk.format(velocity, 2)} m/s`,
    `a = -9.80 m/s²`,
    `h = ${sdk.format(height, 2)} m`
  ];
  const callout = sdk.callout(ballX + 70, ballY - 20, calloutLines, {
    id: "callout.toss"
  });
  frameObjects.push(...callout);

  return {
    frame: {
      width: 640,
      height: 420,
      objects: frameObjects,
      readouts: [
        { id: "motionState", value: mState },
        { id: "gravityState", value: gState }
      ]
    },
    quantities: {
      launchSpeed: v0,
      gravity: g,
      apexTime: tTop,
      apexHeight: hTop,
      velocity: velocity,
      height: height
    }
  };
}
